import { inferScaleType } from '@visx/scale';

import { HistogramRangeAnnotation } from '../../../types/histogram-annotations.js';
import { XScale } from '../../../types/histogram.js';

/**
 * Converts all invalid values into a number closer to zero that is accepted
 * by logarithmic scale.
 *
 * @param value - The value to be sanitized
 * @param scale - The scale to be considered for sanitization. If it's linear, the value it's the same as input. If it's logarithmic, and the value is not part of its domain, then it's sanitized which means it's converted into a Number.EPSILON, the closest number possible to zero.
 */
export const sanitizeNonPositiveValues = (value: number, scale: XScale) => {
  return inferScaleType(scale) === 'log' && value <= 0 ? Number.EPSILON : value;
};

export const calculateLineIndicatorPosition = (
  value: number,
  scale: XScale,
) => {
  const preEvaluatedValue = sanitizeNonPositiveValues(value, scale);

  return scale(preEvaluatedValue);
};

export const calculateAreaIndicatorPosition = (
  value: HistogramRangeAnnotation,
  scale: XScale,
) => {
  const preEvaluatedValueFrom = sanitizeNonPositiveValues(value.from, scale);
  const preEvaluatedValueTo = sanitizeNonPositiveValues(value.to, scale);

  const x = scale(preEvaluatedValueFrom);
  const width = Math.abs(scale(preEvaluatedValueTo) - x);

  return { x, width };
};
